(function(E){ const x = E["hr-m3"] = E["hr-m3"] || {units:{}}; x.units["hr-cp-3"] = {"writing":{"id":"c-hr-cp-3-w","title":{"en":"The rejection email to Sami","tr":"Sami'ye olumsuz yanıt e-postası","fa":"ایمیل عدم پذیرش برای سامی"},"course":"hr","unit":"hr-cp-3","portfolio":"hr-final-5","type":"writing","difficulty":"hard","prompt":{"en":"Sami interviewed for Warehouse Planner, Dubai, and was not chosen. Write his rejection email (60-90 words): thanks, one specific strength, a clear softened no with the passive, an honest reason, an offer of feedback, a kind close.","tr":"Sami, Warehouse Planner, Dubai pozisyonu için mülakata girdi ve seçilmedi. Olumsuz yanıt e-postasını yaz (60-90 kelime): teşekkür, somut bir güçlü yön, edilgen yapıyla yumuşatılmış açık bir hayır, dürüst bir sebep, geri bildirim teklifi, nazik bir kapanış.","fa":"سامی برای موقعیت «Warehouse Planner, Dubai» مصاحبه داد و انتخاب نشد. ایمیل عدم پذیرش او را بنویس (۶۰ تا ۹۰ کلمه): تشکر، اشاره به یک نقطه‌ی قوت مشخص، یک «نه»ی روشن و نرم با فعل مجهول، یک دلیل صادقانه، پیشنهاد بازخورد و یک پایان مهربان."},"model":"Dear Sami, Thank you for coming to the interview for the Warehouse Planner role on Monday. We were impressed by your knowledge of our planning software. I'm afraid that on this occasion the position has been offered to a candidate with more experience of planning large warehouses. This was a close decision. If you would like feedback, I would be happy to call you this week. With your permission, we will keep your details on file. Kind regards, Leyla Karimi","frame":"Dear ___, Thank you for ___. We were impressed by ___. I'm afraid that on this occasion the position has been offered to ___. This was ___. If you would like feedback, ___. Kind regards, ___","words":[{"word":"afraid"},{"word":"offered"},{"word":"feedback"}],"minWords":60,"minSentences":6,"rubric":["Task done: thanks, strength, clear no, reason, feedback offer, close","Organised: positive, news, reason, next step, close","Language: passive; I'm afraid / on this occasion; past simple for the interview","Tone: kind, clear, objective"],"rubricI18n":{"tr":["Görev: teşekkür, güçlü yön, net bir hayır, sebep, geri bildirim teklifi, kapanış","Düzen: olumlu giriş, haber, sebep, sonraki adım, kapanış","Dil: edilgen; I'm afraid / on this occasion; mülakat için past simple","Üslup: nazik, net, nesnel"],"fa":["کامل بودن کار: تشکر، نقطه‌ی قوت، «نه»ی روشن، دلیل، پیشنهاد بازخورد، پایان","نظم: شروع مثبت، خبر، دلیل، قدم بعدی، پایان","زبان: مجهول؛ I'm afraid / on this occasion؛ گذشته‌ی ساده برای مصاحبه","لحن: مهربان، روشن، عینی"]},"parts":[{"t":{"en":"Thanks","tr":"Teşekkür","fa":"تشکر"},"find":["thank you"],"sample":"thanks for the interview on Monday"},{"t":{"en":"One specific strength","tr":"Somut bir güçlü yön","fa":"یک نقطه‌ی قوت مشخص"},"find":["we were impressed","we enjoyed"],"sample":"his knowledge of our planning software"},{"t":{"en":"The clear no","tr":"Net ret","fa":"«نه» روشن"},"find":["i'm afraid","has been offered","on this occasion"],"sample":"the position has been offered to another candidate"},{"t":{"en":"An honest reason","tr":"Dürüst bir gerekçe","fa":"یک دلیل صادقانه"},"find":["with more","experience"],"sample":"more experience of large warehouses"},{"t":{"en":"An offer of feedback and a kind close","tr":"Geri bildirim teklifi ve kibar bir kapanış","fa":"پیشنهاد بازخورد و پایانی مهربان"},"find":["feedback","keep your details"],"sample":"happy to call with feedback; details kept on file"}]},"speaking":{"id":"hr-cp-3-sp","course":"hr","unit":"hr-cp-3","rounds":[180,120],"topic":{"en":"Mini Interview (recorded)","tr":"Kısa Mülakat (kayıtlı)","fa":"مصاحبه‌ی کوتاه (ضبط‌شده)"},"warmup":{"en":"Choose a real role from your workplace, or use \"Warehouse Planner, Dubai\". Note two competencies it needs.","tr":"İşyerinden gerçek bir pozisyon seç ya da \"Warehouse Planner, Dubai\" kullan. Gerektirdiği iki yetkinliği not et.","fa":"یک موقعیت شغلی واقعی از محل کارت انتخاب کن، یا از «Warehouse Planner, Dubai» استفاده کن. دو شایستگی را که این شغل لازم دارد یادداشت کن."},"questions":[{"en":"Open the interview: welcome, the panel, the three parts and the finish time.","tr":"Mülakatı aç: karşılama, panel, üç aşama ve bitiş saati.","fa":"مصاحبه را شروع کن: خوشامد، معرفی هیئت مصاحبه، سه بخش مصاحبه و ساعت پایان."},{"en":"Ask two behavioural questions, one for each competency.","tr":"Her yetkinlik için bir tane olmak üzere iki davranışsal soru sor.","fa":"دو سؤال رفتاری بپرس، برای هر شایستگی یک سؤال."},{"en":"The answer has no result. Ask a follow-up. Then close: next steps and when they will hear from you.","tr":"Cevapta sonuç yok. Bir takip sorusu sor. Sonra kapat: sonraki adımlar ve senden ne zaman haber alacakları.","fa":"جواب متقاضی نتیجه را نگفته است. یک سؤال تکمیلی بپرس. بعد مصاحبه را جمع‌بندی کن: قدم‌های بعدی و اینکه کی خبرش را می‌دهی."}],"followups":[{"en":"Say the whole interview part out loud in 3 minutes, then again in 2 minutes.","tr":"Mülakatın tamamını yüksek sesle söyle: önce 3 dakikada, sonra yeniden 2 dakikada.","fa":"کل مصاحبه را با صدای بلند بگو: یک بار در سه دقیقه و بعد دوباره در دو دقیقه."}],"expressions":[{"phrase":"Let me explain how today is going to work.","meaning":{"en":"Opens with the structure.","tr":"Yapıyla açar.","fa":"با توضیح ساختار، مصاحبه را شروع می‌کند."}},{"phrase":"Tell me about a time when...","meaning":{"en":"Behavioural question.","tr":"Davranışsal soru.","fa":"سؤال رفتاری."}},{"phrase":"You'll hear from us by Friday.","meaning":{"en":"Closes with a clear next step.","tr":"Net bir sonraki adımla kapatır.","fa":"با یک قدم بعدیِ روشن تمام می‌کند."}}]},"perspective":{"id":"c-hr-cp-3-p","title":{"en":"Sami reads your email","tr":"Sami e-postanı okuyor","fa":"سامی ایمیلت را می‌خواند"},"course":"hr","unit":"hr-cp-3","type":"perspective","minSentences":3,"prompt":{"en":"You are Sami reading your email. Write 3 sentences in first person: which line will you remember, how do you feel, and would you apply to Atlas again?","tr":"E-postanı okuyan Sami'sin. Birinci tekil şahısla 3 cümle yaz: hangi satırı hatırlayacaksın, ne hissediyorsun ve Atlas'a yeniden başvurur musun?","fa":"تو سامی هستی و این ایمیل را می‌خوانی. از زبان خودت سه جمله بنویس: کدام جمله در ذهنت می‌ماند، چه حسی داری و آیا باز هم برای Atlas درخواست می‌فرستی؟"}},"exit":{"id":"c-hr-cp-3-x","course":"hr","unit":"hr-cp-3","type":"exit","note":"8 spaced items across modules 1-3.","items":[{"from":"hr-1-1","kind":"blank","prompt":"Leyla usually ___ CVs in the morning.","options":["reads","is reading","read"],"correct":0,"point":2,"why":{"en":"reads: 'usually' is a routine, so present simple with -s. 'Is reading' is happening now, and 'read' doesn't agree with Leyla.","tr":"reads: 'usually' bir rutindir, bu yüzden -s'li geniş zaman. 'Is reading' şu anda olandır; 'read' Leyla ile uyuşmaz.","fa":"⁨reads⁩ درست است، چون ⁨usually⁩ یعنی برنامه‌ی همیشگی و حال ساده با ⁨-s⁩ می‌خواهد. ⁨is reading⁩ یعنی همین الان و ⁨read⁩ با ⁨Leyla⁩ جور نیست."}},{"from":"hr-1-4","kind":"blank","prompt":"She ___ in Dubai twice, in 2019 and 2022.","options":["has worked","worked","has been working"],"correct":1,"point":2,"why":{"en":"worked: the two finished dates (2019 and 2022) take the past simple. 'Has worked' and 'has been working' link to now.","tr":"worked: bitmiş iki tarih (2019 ve 2022) past simple ister. 'Has worked' ve 'has been working' şimdiye bağlar.","fa":"worked درست است، چون دو تاریخ تمام‌شده (۲۰۱۹ و ۲۰۲۲) گذشته‌ی ساده می‌خواهند. has worked و has been working به الان ربط دارند."}},{"from":"hr-2-2","kind":"blank","prompt":"We welcome applicants ___ enjoy working outdoors.","options":["who","which","whose"],"correct":0,"point":2,"why":{"en":"who: it refers to people (applicants). 'Which' is for things, and 'whose' shows ownership.","tr":"who: insanları anlatır (applicants). 'Which' şeyler içindir; 'whose' sahiplik gösterir.","fa":"who درست است، چون به آدم‌ها برمی‌گردد. which برای چیزهاست و whose مالکیت را نشان می‌دهد."}},{"from":"hr-2-4","kind":"blank","prompt":"___ candidates meet the essential requirements.","options":["Both","Neither of","Either"],"correct":0,"point":2,"why":{"en":"Both: two candidates who all meet the requirements, with a plural verb (meet). 'Neither of' would need 'the' and means none; 'Either' takes a singular verb.","tr":"Both: gereklilikleri karşılayan iki aday, çoğul fiille (meet). 'Neither of' 'the' ister ve hiçbiri demektir; 'Either' tekil fiil alır.","fa":"Both درست است، چون دو داوطلب هر دو شرط‌ها را دارند و فعل جمع است (meet). Neither of به the نیاز دارد و یعنی هیچ‌کدام و Either فعل مفرد می‌گیرد."}},{"from":"hr-3-1","kind":"blank","prompt":"Omar ___ us on video at ten.","options":["joining","is joining","is join"],"correct":1,"point":2,"why":{"en":"is joining: a fixed arrangement takes is + -ing. 'Joining' has no be, and 'is join' drops -ing.","tr":"is joining: kesinleşmiş bir düzenleme is + -ing alır. 'Joining'de be yoktur; 'is join' -ing'i düşürür.","fa":"⁨is joining⁩ درست است، چون قرار قطعی ⁨is⁩ و فعل ⁨ing⁩‌دار می‌خواهد. ⁨joining⁩ بدون ⁨be⁩ است و ⁨is join⁩ بدون ⁨-ing⁩."}},{"from":"hr-3-2","kind":"blank","prompt":"Tell me about a time when you ___ a mistake at work.","options":["made","have made","make"],"correct":0,"point":2,"why":{"en":"made: 'a time when' is one finished event, so past simple. 'Have made' and 'make' don't fit a finished story.","tr":"made: 'a time when' bitmiş tek bir olaydır, bu yüzden past simple. 'Have made' ve 'make' bitmiş bir hikâyeye uymaz.","fa":"made درست است، چون a time when یک اتفاق تمام‌شده است و گذشته‌ی ساده می‌خواهد. have made و make با ماجرای تمام‌شده جور نیستند."}},{"from":"hr-3-3","kind":"blank","prompt":"There is ___ evidence of teamwork in her answers.","options":["few","limited","many"],"correct":1,"point":2,"why":{"en":"limited: 'evidence' is uncountable, and 'limited evidence' says there isn't much, carefully. 'Few' and 'many' need countable plurals.","tr":"limited: 'evidence' sayılamaz; 'limited evidence' fazla kanıt olmadığını dikkatlice söyler. 'Few' ve 'many' sayılabilen çoğul ister.","fa":"limited درست است، چون evidence شمارش‌ناپذیر است و limited evidence محتاطانه می‌گوید شاهد زیادی نیست. few و many اسم جمعِ شمارش‌پذیر می‌خواهند."}},{"from":"hr-3-4","kind":"blank","prompt":"The role ___ to another candidate.","options":["has offered","has been offered","offering"],"correct":1,"point":2,"why":{"en":"has been offered: the role receives the action, so has been + past participle. 'Has offered' says the role offered something, and 'offering' has no be.","tr":"has been offered: görev eylemi alır, bu yüzden has been + üçüncü hâl. 'Has offered' görevin bir şey önerdiğini söyler; 'offering'de be yoktur.","fa":"has been offered درست است، چون سمت به کسی پیشنهاد شده و has been و اسم مفعول لازم است. has offered یعنی خود سمت چیزی پیشنهاد داده و offering بدون be است."}}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
